import sys
import re

def main():
    text = sys.stdin.read()
    env = {}
    names = list("abcdefghijklmnop") + ["TMP"]
    for n in names:
        env[n] = 0

    stmt_re = re.compile(r'^\s*([A-Za-z_][A-Za-z_0-9]*)\s*<-\s*(-?\d+|[A-Za-z_][A-Za-z_0-9]*)\s*$')
    # Split on newlines and semicolons; strip comments
    for line in text.splitlines():
        idx = line.find('//')
        if idx != -1:
            line = line[:idx]
        for part in line.split(';'):
            part = part.strip()
            if not part:
                continue
            m = stmt_re.match(part)
            if not m:
                continue
            target, src = m.group(1), m.group(2)
            if re.fullmatch(r'-?\d+', src):
                val = int(src)
            else:
                val = env.get(src, 0)
            env[target] = val

    out = "; ".join(f"{n} ?= {env.get(n, 0)}" for n in names) + ";"
    print(out)

if __name__ == "__main__":
    main()
